// Europa Clipper mug explainer: station metadata (labels, controls, readouts), part names, mug pop-ups, credits.
// GENERATED by tools/page/gen_copy.py from tools/page/content.src.js + PLAN.md (sections E.5 and A). Edit the sources, not this file.
// The prose of every station lives in index.html (pasted from PLAN.md section A).

// The only place the owner's first name is written. Every copy string carries the token {{OWNER}} (PLAN.md and the generator);
// to switch to "the mug's owner", change this one constant and run `python tools/page/gen_copy.py`.
export const OWNER_NAME = 'Kevin';
const own = (s) => s.replaceAll('{{OWNER}}', OWNER_NAME);
const ownPopups = (P) => { for (const g of Object.values(P)) for (const f of ['title', 'eli5', 'eng']) g[f] = own(g[f]); return P; };

const C = { ice: '#8fd3ff', gold: '#ffca00', pur: '#a98bff', red: '#ff6a8b', grn: '#5ef0a8', gry: '#c9d3e2' };
const u = (v, unit, d = 0) => (v == null || Number.isNaN(+v) ? '—' : (+v).toLocaleString('en-US', { maximumFractionDigits: d, minimumFractionDigits: d }) + `<i>${unit}</i>`);
const deg = (v) => u(v, '°', 0);
const bar = (v) => (v == null ? '—' : '<b class="mb"><s style="width:' + Math.round(Math.min(1, Math.abs(v)) * 100) + '%"></s></b>');
const yn = (v, a, b) => (v == null ? '—' : v ? `<span class="c-grn">${a}</span>` : `<span class="c-red">${b}</span>`);

// label: a = stage anchor name, t = text, side 'l' opens to the left
const L = (a, t, c, side) => ({ a, t, c: c || C.ice, side });

// control builders (rendered by main.js)
const slider = (key, label, min, max, step, v, show, track) => ({ t: 'slider', key, label, min, max, step, v, show, track });
const toggle = (key, label, v) => ({ t: 'toggle', key, label, v });
const seg = (key, label, opts, v) => ({ t: 'seg', key, label, opts, v });
const btn = (label, o) => ({ t: 'btn', label, ...o });

